#!/usr/bin/env python3
"""Materialize an existing native Bazel closure into a private relocatable tree.

The input workspace is read as syntax, never executed. Source file symlinks are
copied as bytes; repository locations in the output are relative to WORKSPACE.
No source archive is uploaded or committed by this command.
"""
import argparse
import ast
import hashlib
import json
from pathlib import Path, PurePosixPath
import re
import shutil


LABEL = re.compile(r"@{0,2}([^/]*)//([^:]*):(.+)")
SKIP = {".git", ".DS_Store", "__pycache__"}
# Generated by Bazel or the preserved rules_python workspace initialization.
BAZEL_OWNED = {"bazel_tools", "local_config_cc", "local_config_platform", "host_platform",
               "internal_platforms_do_not_use", "rules_python_internal", "platforms"}
HOST_REPOSITORIES = {"cuda", "cudnn", "infiniband", "python-runtime", "java-runtime", "hadoop-runtime"}


def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def repositories(workspace):
    result = {}
    for node in ast.parse((workspace / "WORKSPACE").read_text()).body:
        if not isinstance(node, ast.Expr) or not isinstance(node.value, ast.Call):
            continue
        call = node.value
        if not isinstance(call.func, ast.Name) or call.func.id != "local_repository":
            continue
        values = {k.arg: ast.literal_eval(k.value) for k in call.keywords}
        name, location = values["name"], values["path"]
        if not re.fullmatch(r"[A-Za-z0-9_.+~-]+", name) or name in result:
            raise ValueError("invalid or duplicate repository name")
        result[name] = (workspace / location).resolve(strict=True)
    return result


def labels(path):
    for text in path.read_text().splitlines():
        match = LABEL.fullmatch(text.strip())
        if match:
            yield text.strip(), match.groups()


def relative_file(package, name):
    # Reject traversal before normalization, including target names such as ../x.
    for part in (package, name):
        if part.startswith("/") or ".." in PurePosixPath(part).parts:
            raise ValueError("label escapes its repository")
    return Path(package) / name


def build_bundle(workspace, deps, buildfiles, output, full_trees=("entropy",)):
    workspace = workspace.resolve(strict=True)
    output = output.resolve()
    if output.exists():
        raise FileExistsError("bundle output already exists")
    if output.is_relative_to(workspace):
        raise ValueError("output must be outside the input workspace")
    repos = repositories(workspace)
    roots = {"": workspace, **repos}
    framework_roots = [(workspace / relative_file("", tree)).resolve(strict=True) for tree in full_trees]
    if any(output.is_relative_to(root) for root in [*repos.values(), *framework_roots]):
        raise ValueError("output must be outside original source repositories")
    # Validate both complete query inputs before copying a large SDK archive.
    for query, required in ((deps, False), (buildfiles, True)):
        for label, (repo, package, name) in labels(query):
            relative = relative_file(package, name)
            if repo not in roots:
                if repo not in BAZEL_OWNED:
                    raise ValueError("unmapped query repository: " + repo)
            elif required and not (roots[repo] / relative).is_file():
                raise FileNotFoundError("missing build metadata: " + label)
    output.mkdir(parents=True)
    copied = {}
    unresolved = []

    def copy_file(source, destination):
        key = destination.relative_to(output).as_posix()
        if key in copied:
            return
        destination.parent.mkdir(parents=True, exist_ok=True)
        # copyfile follows source symlinks; the destination is always a real file.
        shutil.copyfile(source, destination)
        destination.chmod(source.stat().st_mode & 0o777)
        copied[key] = {"bytes": destination.stat().st_size, "sha256": sha256(destination)}

    def copy_tree(source, destination, ancestors=frozenset()):
        real = source.resolve(strict=True)
        if real in ancestors:
            raise ValueError("cyclic directory symlink")
        destination.mkdir(parents=True, exist_ok=True)
        for child in sorted(source.iterdir()):
            if child.name in SKIP or child.name.startswith("bazel-"):
                continue
            if child.is_dir():
                copy_tree(child, destination / child.name, ancestors | {real})
            elif child.is_file():
                copy_file(child, destination / child.name)
            elif child.is_symlink():
                raise FileNotFoundError("dangling source symlink: " + str(child))

    def destination(repo, relative):
        return output / "repositories" / repo / relative if repo else output / relative

    for query, required in ((deps, False), (buildfiles, True)):
        for label, (repo, package, name) in labels(query):
            relative = relative_file(package, name)
            if repo not in roots:
                # Bazel-owned repositories are re-created by the same Bazel release.
                if repo not in BAZEL_OWNED:
                    raise ValueError("unmapped query repository: " + repo)
                continue
            source = roots[repo] / relative
            if source.is_file():
                copy_file(source, destination(repo, relative))
            elif required:
                raise FileNotFoundError("missing build metadata: " + label)
            else:
                unresolved.append(label)  # Rules and generated outputs have no source file.

    for name, root in repos.items():
        dest = output / "repositories" / name
        dest.mkdir(parents=True, exist_ok=True)
        for metadata in ("BUILD", "BUILD.bazel", "WORKSPACE", "WORKSPACE.bazel", ".VERSION"):
            if (root / metadata).is_file():
                copy_file(root / metadata, dest / metadata)
        if not (dest / "WORKSPACE").exists() and not (dest / "WORKSPACE.bazel").exists():
            (dest / "WORKSPACE").write_text("")
        # Workspace-loaded rule files are outside buildfiles(deps(...)). Preserve
        # complete rule repositories so py_repositories() can run after relocation.
        if root.is_relative_to(workspace / "cached-rules"):
            copy_tree(root, dest)

    copy_tree(workspace / ".resources", output / ".resources")
    for tree in full_trees:
        relative = relative_file("", tree)
        copy_tree(workspace / relative, output / relative)
    if (workspace / "BUILD").is_file():
        copy_file(workspace / "BUILD", output / "BUILD")

    original = (workspace / "WORKSPACE").read_text()
    parsed = ast.parse(original)
    lines = original.splitlines(keepends=True)
    for node in reversed(parsed.body):
        if (isinstance(node, ast.Expr) and isinstance(node.value, ast.Call)
                and isinstance(node.value.func, ast.Name)
                and node.value.func.id == "local_repository"):
            name = next(ast.literal_eval(k.value) for k in node.value.keywords if k.arg == "name")
            lines[node.lineno - 1:node.end_lineno] = [
                f'local_repository(name = {json.dumps(name)}, path = "repositories/{name}")\n']
    (output / "WORKSPACE").write_text("".join(lines))
    manifest = dict(schema=1, repository_count=len(repos), source_files=len(copied),
                    source_bytes=sum(v["bytes"] for v in copied.values()), files=copied,
                    dependency_labels_without_local_file=unresolved,
                    workspace_sha256=sha256(output / "WORKSPACE"),
                    native_build_completed=False, runtime_training_completed=False)
    (output / "bundle-manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
    return manifest


def audit_bundle(workspace, sourcefiles):
    """Verify materialized bytes and distinguish generated rules from source files."""
    workspace = workspace.resolve(strict=True)
    manifest = json.loads((workspace / "bundle-manifest.json").read_text())
    if sha256(workspace / "WORKSPACE") != manifest["workspace_sha256"]:
        raise ValueError("bundle WORKSPACE hash mismatch")
    for name, expected in manifest["files"].items():
        path = workspace / relative_file("", name)
        if path.is_symlink() or not path.is_file() or sha256(path) != expected["sha256"]:
            raise ValueError("bundle file hash mismatch: " + name)
    roots = {"": workspace, **repositories(workspace)}
    if any(not path.is_relative_to(workspace) for path in roots.values()):
        raise ValueError("bundle repository escapes its workspace")
    host_inputs, source_count = [], 0
    for label, (repo, package, name) in labels(sourcefiles):
        relative = relative_file(package, name)
        if repo in BAZEL_OWNED:
            continue
        if repo not in roots:
            raise ValueError("unmapped source repository: " + repo)
        source_count += 1
        path = roots[repo] / relative
        if not path.is_file():
            if repo in HOST_REPOSITORIES:
                host_inputs.append(label)
            else:
                raise FileNotFoundError("missing source input: " + label)
    return dict(verified_files=len(manifest["files"]), source_labels=source_count,
                required_host_inputs=host_inputs, native_build_completed=False,
                runtime_training_completed=False)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, required=True)
    parser.add_argument("--audit", action="store_true")
    for name in ("deps", "buildfiles", "output", "sourcefiles"):
        parser.add_argument("--" + name, type=Path)
    args = parser.parse_args()
    if args.audit:
        if args.sourcefiles is None:
            parser.error("--audit requires --sourcefiles from kind('source file', deps(...))")
        print(json.dumps(audit_bundle(args.workspace, args.sourcefiles)))
        return
    if any(getattr(args, name) is None for name in ("deps", "buildfiles", "output")):
        parser.error("building requires --deps, --buildfiles and --output")
    result = build_bundle(args.workspace, args.deps, args.buildfiles, args.output)
    print(json.dumps({k: v for k, v in result.items() if k not in {"files", "dependency_labels_without_local_file"}}))


if __name__ == "__main__":
    main()
